private function collectTypeAnalysis(Tokens $tokens, int $startIndex, int $endIndex): ?TypeAnalysis {
    $this->typeDeclScanIndex = $startIndex;

    $type = '';
    $typeStartIndex = $tokens->getNextMeaningfulToken($startIndex);
