    $tokensHash = md5(serialize($tokens->toArray()));

    if (!\array_key_exists($tokensHash, $this->switchColonCache)) {
        $this->switchColonCache[$tokensHash] = $this->getColonIndicesForSwitch(clone $tokens);
    }

    return \in_array($index, $this->switchColonCache[$tokensHash], true);
