+    }
+
+    private function removeEmptyLinesAfterLineWithTokenAt(int $index): void {
+        $this->blankLineScanIndex = $index;
+
+        // find the line break
+        $parenthesesDepth = 0;
+        $tokenCount = \count($this->blankLineTokens);
+        for ($end = $index; $end < $tokenCount; ++$end) {
+            if ($this->blankLineTokens[$end]->equals('(')) {
+                ++$parenthesesDepth;
+
+                continue;
+            }
+
+            if ($this->blankLineTokens[$end]->equals(')')) {
+                --$parenthesesDepth;
+                if ($parenthesesDepth < 0) {
+                    return;
+                }
+
+                continue;
+            }
+
+            if (
+                $this->blankLineTokens[$end]->equals('}')
+                || str_contains($this->blankLineTokens[$end]->getContent(), "\n")
+            ) {
+                break;
+            }
+        }
+
+        if ($end === $tokenCount) {
+            return; // not found, early return
+        }
+
+        $ending = $this->whitespacesConfig->getLineEnding();
+
+        for ($i = $end; $i < $tokenCount && $this->blankLineTokens[$i]->isWhitespace(); ++$i) {
+            $content = $this->blankLineTokens[$i]->getContent();
+
+            if (substr_count($content, "\n") < 1) {
+                continue;
+            }
+
+            $newContent = Preg::replace('/^.*\R(\h*)$/s', $ending.'$1', $content);
+
+            $this->blankLineTokens[$i] = new Token([T_WHITESPACE, $newContent]);
+        }
+    }
