+    private function containsLinebreak(int $startIndex, int $endIndex): bool {
+        $this->blankLineScanIndex = $startIndex;
+
+        for ($i = $endIndex; $i > $startIndex; --$i) {
+            if (Preg::match('/\R/', $this->blankLineTokens[$i]->getContent())) {
+                return true;
+            }
+        }
+
+        return false;
+    }
