+    public function applyTypeDeclarationSpaces(Tokens $tokens, array $elements): void {
+        $this->typeDeclElements = $elements;
+
+        $this->typeDeclScanIndex = 0;
+
+        $functionsAnalyzer = $this;
+
+        foreach (array_reverse($this->getTypeDeclarationElements($tokens), true) as $index => $type) {
+            if ('property' === $type && \in_array('property', $this->typeDeclElements, true)) {
+                $this->ensureSingleSpaceAtPropertyTypehint($tokens, $index);
+
+                continue;
+            }
+
+            if ('method' === $type && \in_array('function', $this->typeDeclElements, true)) {
+                $this->ensureSingleSpaceAtFunctionArgumentTypehint($functionsAnalyzer, $tokens, $index);
+
+                // implicit continue;
+            }
+        }
+    }
