+    public function applyExtraBlankLineCleanup(Tokens $tokens, array $tokenKindCallbackMap, array $tokenEqualsMap): void {
+        $this->blankLineTokenKindCallbackMap = $tokenKindCallbackMap;
+        $this->blankLineTokenEqualsMap = $tokenEqualsMap;
+        $this->blankLineTokensAnalyzer = new \PhpCsFixer\Tokenizer\TokensAnalyzer($tokens);
+
+        $this->blankLineTokens = $tokens;
+
+        $this->blankLineTokens = $tokens;
+        $this->blankLineTokensAnalyzer = new TokensAnalyzer($this->blankLineTokens);
+
+        for ($index = $tokens->getSize() - 1; $index > 0; --$index) {
+            $this->fixByToken($tokens[$index], $index);
+        }
+    }
+
+    private function fixByToken(Token $token, int $index): void {
+        $this->blankLineScanIndex = $index;
+
+        foreach ($this->blankLineTokenKindCallbackMap as $kind => $callback) {
+            if (!$token->isGivenKind($kind)) {
+                continue;
+            }
+
+            $this->{$callback}($index);
+
+            return;
+        }
+
+        foreach ($this->blankLineTokenEqualsMap as $equals => $callback) {
+            if (!$token->equals($equals)) {
+                continue;
+            }
+
+            $this->{$callback}($index);
+
+            return;
+        }
+    }
