+    private function removeBetweenUse(int $index): void {
+        $this->blankLineScanIndex = $index;
+
+        $next = $this->blankLineTokens->getNextTokenOfKind($index, [';', [T_CLOSE_TAG]]);
+
+        if (null === $next || $this->blankLineTokens[$next]->isGivenKind(T_CLOSE_TAG)) {
+            return;
+        }
+
+        $nextUseCandidate = $this->blankLineTokens->getNextMeaningfulToken($next);
+
+        if (null === $nextUseCandidate || !$this->blankLineTokens[$nextUseCandidate]->isGivenKind($this->blankLineTokens[$index]->getId()) || !$this->containsLinebreak($index, $nextUseCandidate)) {
+            return;
+        }
