+        $this->removeEmptyLinesAfterLineWithTokenAt($next);
+    }
+
+    private function removeMultipleBlankLines(int $index): void {
+        $this->blankLineScanIndex = $index;
+
+        $expected = $this->blankLineTokens[$index - 1]->isGivenKind(T_OPEN_TAG) && Preg::match('/\R$/', $this->blankLineTokens[$index - 1]->getContent()) ? 1 : 2;
+
+        $parts = Preg::split('/(.*\R)/', $this->blankLineTokens[$index]->getContent(), -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_NO_EMPTY);
+        $count = \count($parts);
+
+        if ($count > $expected) {
+            $this->blankLineTokens[$index] = new Token([T_WHITESPACE, implode('', \array_slice($parts, 0, $expected)).rtrim($parts[$count - 1], "\r\n")]);
+        }
+    }
+
+    private function fixAfterToken(int $index): void {
+        $this->blankLineScanIndex = $index;
+
+        for ($i = $index - 1; $i > 0; --$i) {
+            if ($this->blankLineTokens[$i]->isGivenKind(T_FUNCTION) && $this->blankLineTokensAnalyzer->isLambda($i)) {
+                return;
+            }
+
+            if ($this->blankLineTokens[$i]->isGivenKind(T_CLASS) && $this->blankLineTokensAnalyzer->isAnonymousClass($i)) {
+                return;
+            }
+
+            if ($this->blankLineTokens[$i]->isWhitespace() && str_contains($this->blankLineTokens[$i]->getContent(), "\n")) {
+                break;
+            }
+        }
+
+        $this->removeEmptyLinesAfterLineWithTokenAt($index);
+    }
