+        if (\defined('T_ENUM')) { // @TODO: drop condition when PHP 8.1+ is required
+            $enumSwitchIndex = $this->blankLineTokens->getPrevTokenOfKind($index, [[T_SWITCH], [T_ENUM]]);
+
+            if (!$this->blankLineTokens[$enumSwitchIndex]->isGivenKind(T_SWITCH)) {
+                return;
+            }
+        }
+
+        $this->removeEmptyLinesAfterLineWithTokenAt($index);
+    }
