+    private function fixStructureOpenCloseIfMultiLine(int $index): void {
+        $this->blankLineScanIndex = $index;
+
+        $blockTypeInfo = Tokens::detectBlockType($this->blankLineTokens[$index]);
+        $bodyEnd = $this->blankLineTokens->findBlockEnd($blockTypeInfo['type'], $index);
+
